DROP TABLE IF EXISTS tecc_data_type_test2 CASCADE;
DROP TABLE IF EXISTS tecc_tecc_data_type_test2 CASCADE;
DROP DEK IF EXISTS dek_t1 CASCADE;
DROP DEK IF EXISTS dek_t2 CASCADE;
DROP KEK IF EXISTS kek_t1 CASCADE;
CREATE KEK kek_t1 WITH (KEY_STORE=localkms, KEY_PATH='/tmp/kek_t1.key');
CREATE DEK dek_t1 WITH VALUES (KEK=kek_t1);
CREATE DEK dek_t2 WITH VALUES (KEK=kek_t1);
CREATE TABLE tecc_data_type_test2 (id SERIAL PRIMARY KEY, text_col text_enc encrypted with (dek = dek_t1), varchar_col varchar_enc encrypted with (dek = dek_t1), bpchar_col bpchar_enc encrypted with (dek = dek_t1), int2_col int2_enc encrypted with (dek = dek_t1), int4_col int4_enc encrypted with (dek = dek_t1), int8_col int8_enc encrypted with (dek = dek_t1), numeric_col numeric_enc encrypted with (dek = dek_t1), float4_col float4_enc encrypted with (dek = dek_t1), float8_col float8_enc encrypted with (dek = dek_t1));
CREATE TABLE tecc_tecc_data_type_test2 (id SERIAL PRIMARY KEY, text_col text_enc encrypted with (dek = dek_t2), varchar_col varchar_enc encrypted with (dek = dek_t2), bpchar_col bpchar_enc encrypted with (dek = dek_t2), int2_col int2_enc encrypted with (dek = dek_t2), int4_col int4_enc encrypted with (dek = dek_t2), int8_col int8_enc encrypted with (dek = dek_t2), numeric_col numeric_enc encrypted with (dek = dek_t2), float4_col float4_enc encrypted with (dek = dek_t2), float8_col float8_enc encrypted with (dek = dek_t2));
