SELECT a.id, b.id FROM tecc_tecc_data_type_test2 a, tecc_data_type_test2 b WHERE a.int2_col = b.int2_col AND a.int4_col = b.int4_col AND a.int8_col = b.int8_col AND a.numeric_col = b.numeric_col AND a.float4_col = b.float4_col AND a.float8_col = b.float8_col AND a.text_col = b.text_col AND a.varchar_col = b.varchar_col AND a.bpchar_col = b.bpchar_col;
SELECT a.id, a.int4_col, a.int8_col, b.id, b.int4_col, b.int8_col FROM tecc_tecc_data_type_test2 a, tecc_data_type_test2 b WHERE a.int4_col > b.int4_col AND a.int8_col < b.int8_col;
SELECT a.id, a.numeric_col, a.float4_col, b.id, b.numeric_col, b.float4_col FROM tecc_tecc_data_type_test2 a, tecc_data_type_test2 b WHERE a.numeric_col >= b.numeric_col AND a.float4_col <= b.float4_col;
SELECT a.id, a.text_col, a.int2_col, b.id, b.text_col, b.int2_col FROM tecc_tecc_data_type_test2 a, tecc_data_type_test2 b WHERE a.text_col = b.text_col AND a.int2_col > b.int2_col;
SELECT a.id, a.varchar_col, a.int4_col, b.id, b.varchar_col, b.int4_col FROM tecc_tecc_data_type_test2 a, tecc_data_type_test2 b WHERE a.varchar_col = b.varchar_col AND a.int4_col < b.int4_col;
SELECT a.id, a.bpchar_col, a.int8_col, b.id, b.bpchar_col, b.int8_col FROM tecc_tecc_data_type_test2 a, tecc_data_type_test2 b WHERE a.bpchar_col = b.bpchar_col AND a.int8_col >= b.int8_col;
